export default function ({ files, token, previous }) {
  const rows = [...(previous?.files ?? []), ...files];
  const seen = previous?.tokens ?? [];
  if (token && seen.includes(token)) throw Error("Repeated Drive page token");
  return {
    state: { files: rows, tokens: token ? [...seen, token] : seen },
    more: !!token,
    token: token || null,
  };
}

