export default async function ({ requestId, files }, ctx) {
  if (!requestId.trim()) throw Error("Provide a stable rebuild ID");
  const key = "company-rebuild:" + requestId,
    s = await ctx.state.get(key);
  if (s?.status === "pending")
    throw Error("Inspect Qdrant and reconcile pending rebuild before retrying");
  if (s?.status === "done") return { key, skip: true, files, hasFiles: files.length > 0 };
  await ctx.state.set(key, { status: "pending" });
  return { key, skip: false, files, hasFiles: files.length > 0 };
}

