import { createHash } from "node:crypto";
export default function ({ body, file, previous }) {
  if (!Array.isArray(body?.documents)) throw Error("Missing parsed documents");
  const index = previous?.fileId === file.id ? previous.index : 0,
    more = index < body.documents.length,
    d = body.documents[index];
  if (more && (typeof d?.content !== "string" || !d.content.trim()))
    throw Error("Invalid parsed document");
  const h = createHash("sha256")
      .update(file.id + ":" + index)
      .digest("hex")
      .slice(0, 32),
    id =
      h.slice(0, 8) +
      "-" +
      h.slice(8, 12) +
      "-4" +
      h.slice(13, 16) +
      "-a" +
      h.slice(17, 20) +
      "-" +
      h.slice(20);
  return {
    more,
    state: { fileId: file.id, index: index + 1 },
    chunk: more
      ? {
          id,
          content: d.content,
          metadata: { ...(d.metadata ?? {}), fileId: file.id, fileName: file.name },
        }
      : { id, content: "", metadata: {} },
  };
}

